    private static Variant Get(Settings d, string key, Variant fallback = default) => d.TryGetValue(key, out var value) ? value : fallback;
    private static int Mod(int value, int divisor) => (value % divisor + divisor) % divisor;
    private static string Id() { using var crypto = new Crypto(); return Convert.ToHexString(crypto.GenerateRandomBytes(16)).ToLowerInvariant(); }
    public GArray styles() => Json.ParseString(NamesJson).AsGodotArray();
    public Settings scales() => Json.ParseString(ScaleJson).AsGodotDictionary();
    private static readonly System.Collections.Generic.Dictionary<string,int[]> Intervals = BuildIntervals();
    private static System.Collections.Generic.Dictionary<string,int[]> BuildIntervals() { var result = new System.Collections.Generic.Dictionary<string,int[]>(); foreach(var pair in Json.ParseString(ScaleJson).AsGodotDictionary()) { var values=pair.Value.AsGodotArray(); var items=new int[values.Count];for(int i=0;i<items.Length;++i)items[i]=values[i].AsInt32();result[pair.Key.AsString()]=items;}return result; }
    private static int[] Scale(string name) => Intervals.TryGetValue(name, out var values) ? values : Intervals["major"];
    public int key_pitch(Variant key)
    {
        if (key.VariantType is Variant.Type.Int or Variant.Type.Float) return Mod((int)key.AsDouble(),12);
        return key.AsString().ToUpperInvariant() switch { "C#" or "DB" => 1, "D" => 2, "D#" or "EB" => 3, "E" => 4, "F" => 5, "F#" or "GB" => 6, "G" => 7, "G#" or "AB" => 8, "A" => 9, "A#" or "BB" => 10, "B" => 11, _ => 0 };
    }
    public int scale_pitch(int degree, int root, string scale) { var intervals = Scale(scale); return root + (int)Math.Floor((double)degree / intervals.Length) * 12 + intervals[Mod(degree, intervals.Length)]; }
    public int quantize_pitch(int pitch, Variant key, string scale) { var intervals = Scale(scale); int root = key_pitch(key); for(int distance=0;distance<12;++distance)foreach(int direction in new[]{-1,1}){int candidate=pitch+distance*direction;if(candidate>=0&&candidate<=127&&Array.IndexOf(intervals,Mod(candidate-root,12))>=0)return candidate;}return Math.Clamp(pitch,0,127); }
    public Godot.Collections.Array<int> chord(int root,string scale,int degree,int inversion,bool seventh)
    {
        var values=new System.Collections.Generic.List<int>();for(int i=0;i<(seventh?4:3);++i)values.Add(scale_pitch(degree+i*2,root,scale));for(int i=0;i<Mod(inversion,values.Count);++i)values[i]+=12;values.Sort();var result=new Godot.Collections.Array<int>();foreach(int value in values)result.Add(value);return result;
    }
    public Godot.Collections.Array<int> voice_lead(GArray pitches,GArray previous)
    {
        var best=new Godot.Collections.Array<int>();double bestCost=double.PositiveInfinity;
        for(int inversion=0;inversion<pitches.Count;++inversion)foreach(int octave in new[]{-12,0,12}){var candidate=new System.Collections.Generic.List<int>();for(int i=0;i<pitches.Count;++i)candidate.Add(pitches[i].AsInt32()+octave+(i<inversion?12:0));candidate.Sort();double cost=0;for(int i=0;i<candidate.Count;++i)cost+=Math.Abs(candidate[i]-(previous.Count>0?previous[Math.Min(i,previous.Count-1)].AsInt32():60+i*4));if(cost<bestCost){bestCost=cost;best.Clear();foreach(int value in candidate)best.Add(value);}}return best;
    }
    public GArray chord_suggestions(int degree,string scale) { int[][] choices={new[]{3,4,5,1},new[]{4,6},new[]{5,3},new[]{4,0,1},new[]{0,5},new[]{3,1,4},new[]{0,2}};var result=new GArray();foreach(int next in choices[Mod(degree,7)])result.Add(new Settings{["degree"]=next,["pitches"]=chord(60,scale,next,0,false)});return result; }
    public Settings new_note(int pitch,double start,double duration,double velocity,double pan) => new Settings{["id"]=Id(),["pitch"]=Math.Clamp(pitch,0,127),["start"]=Math.Max(0,start),["duration"]=Math.Max(.001,duration),["velocity"]=Math.Clamp(velocity,0,1),["pan"]=Math.Clamp(pan,-1,1)};
    public Settings note(int pitch,double start,double duration,double velocity,string role,string section,int index,long seed) => new Settings{["id"]=(role+":"+section+":"+index+":"+seed).Sha256Text()[..32],["pitch"]=Math.Clamp(pitch,0,127),["start"]=Math.Max(0,start),["duration"]=Math.Max(.001,duration),["velocity"]=Math.Clamp(velocity,0,1),["pan"]=0.0,["section_id"]=section};
    public Settings style(string name) { string id=name.ToLowerInvariant().Replace('-','_').Replace(' ','_');var common=Json.ParseString(CommonJson).AsGodotDictionary();common["id"]=id;var definitions=Json.ParseString(StyleJson).AsGodotDictionary();if(definitions.TryGetValue(id,out var details))common.Merge(details.AsGodotDictionary(),true);return common; }
    public void append_note(Settings part,int pitch,double start,double duration,double velocity,string section,long seed){var notes=part["notes"].AsGodotArray();notes.Add(note(pitch,start,duration,velocity,part["role"].AsString(),section,notes.Count,seed));}
    public int nearest_chord(int pitch,GArray pitches){int nearest=pitch,distance=999;foreach(var raw in pitches)foreach(int octave in new[]{-12,0,12,24}){int candidate=raw.AsInt32()+octave;if(Math.Abs(candidate-pitch)<distance){distance=Math.Abs(candidate-pitch);nearest=candidate;}}return nearest;}
    public Settings section_at(GArray sections,double beat){foreach(var raw in sections){var section=raw.AsGodotDictionary();if(beat>=section["start"].AsDouble()&&beat<section["start"].AsDouble()+section["duration"].AsDouble())return section;}return sections[sections.Count-1].AsGodotDictionary();}
    public bool ends_section(Settings section,double beat)=>beat>=section["start"].AsDouble()+section["duration"].AsDouble()-.001;
    public Godot.Collections.Array<Settings> pattern_notes(Settings pattern,int repeats,long seed)
    {
        var result=new System.Collections.Generic.List<Settings>();var lanes=Get(pattern,"lanes",new GArray()).AsGodotArray();int steps=Math.Clamp(Get(pattern,"steps",16).AsInt32(),1,256);double length=Math.Clamp(Get(pattern,"length",4.0).AsDouble(),.0625,64),swing=Math.Clamp(Get(pattern,"swing",0.0).AsDouble(),-.45,.45);bool solo=false;foreach(var raw in lanes)if(Get(raw.AsGodotDictionary(),"solo",false).AsBool())solo=true;using var rng=new RandomNumberGenerator{Seed=unchecked((ulong)seed)};
        for(int repeat=0;repeat<Math.Clamp(repeats,1,256);++repeat)for(int laneIndex=0;laneIndex<lanes.Count;++laneIndex)
        {
            var lane=lanes[laneIndex].AsGodotDictionary();if(Get(lane,"mute",false).AsBool()||(solo&&!Get(lane,"solo",false).AsBool()))continue;var values=Get(lane,"values",new GArray()).AsGodotArray();
            for(int step=0;step<Math.Min(steps,values.Count);++step){var entry=values[step];var cell=entry.VariantType==Variant.Type.Dictionary?entry.AsGodotDictionary():new Settings{["velocity"]=entry.AsDouble(),["enabled"]=entry.AsDouble()>0};if(!Get(cell,"enabled",true).AsBool()||rng.Randf()>Math.Clamp(Get(cell,"probability",1.0).AsDouble(),0,1))continue;double velocity=Math.Clamp(Get(cell,"velocity",.8).AsDouble()*(Get(cell,"accent",false).AsBool()?1.2:1),0,1);if(velocity<=0)continue;int ratchets=Math.Clamp(Get(cell,"ratchets",1).AsInt32(),1,8);double stepBeats=length/steps,swung=stepBeats*(step%2==1?1-swing:1+swing);for(int ratchet=0;ratchet<ratchets;++ratchet){double start=repeat*length+step*stepBeats+(step%2==1?swing*stepBeats:0)+ratchet*swung/ratchets;if(start>=(repeat+1)*length)continue;result.Add(note(Get(lane,"pitch",36).AsInt32(),start,Math.Min(swung*.8/ratchets,(repeat+1)*length-start),velocity,laneIndex.ToString(),repeat.ToString(),result.Count,seed));}}
        }
        result.Sort((a,b)=>a["start"].AsDouble().CompareTo(b["start"].AsDouble()));var output=new Godot.Collections.Array<Settings>();foreach(var item in result)output.Add(item);return output;
    }
    public Settings drum_pattern(string style,double energy,double complexity,bool fill,long seed)
    {
        var lanes=new Godot.Collections.Array<Settings>();using var rng=new RandomNumberGenerator{Seed=unchecked((ulong)seed)};
        foreach(int pitch in new[]{36,38,42,46}){var values=new GArray();for(int step=0;step<16;++step){bool enabled=false;double velocity=.6;switch(pitch){case 36:enabled=style=="four_floor"?step%4==0:step is 0 or 8;if(style=="pulse")enabled=step is 0 or 3 or 8 or 11;if(complexity>.6&&step is 6 or 14&&style!="light")enabled=true;velocity=.65+energy*.3;break;case 38:enabled=step is 4 or 12&&style!="pulse";if(style=="cinematic")enabled=step is 6 or 12;if(fill&&step>=12)enabled=step%(complexity>.65?1:2)==0;velocity=.52+energy*.3;break;case 42:enabled=step%(energy>.8?1:2)==0&&style is not "pulse" and not "cinematic";if(style=="light")enabled=step is 2 or 6 or 10 or 14;velocity=(step%4==2?.32:.46)+energy*.1;break;case 46:enabled=step==14&&energy>.45&&style is not "light" and not "pulse" and not "cinematic";velocity=.42+energy*.15;break;}values.Add(new Settings{["enabled"]=enabled,["velocity"]=Math.Clamp(velocity+rng.RandfRange(-.04f,.04f),0,1),["probability"]=1.0,["ratchets"]=1,["accent"]=step==0});}lanes.Add(new Settings{["id"]="drum_"+pitch,["pitch"]=pitch,["mute"]=false,["solo"]=false,["values"]=values});}
        return new Settings{["id"]=Id(),["steps"]=16,["length"]=4.0,["swing"]=style is "lofi" or "jazz"?.2:0.0,["lanes"]=lanes};
    }
    public GArray quantize_notes(GArray notes,double grid,double strength){var result=notes.Duplicate(true);double interval=Math.Max(.001,grid),amount=Math.Clamp(strength,0,1);foreach(var raw in result){var note=raw.AsGodotDictionary();double start=note["start"].AsDouble(),duration=note["duration"].AsDouble();note["start"]=Mathf.Lerp(start,Math.Round(start/interval,MidpointRounding.AwayFromZero)*interval,amount);note["duration"]=Math.Max(interval,Mathf.Lerp(duration,Math.Round(duration/interval,MidpointRounding.AwayFromZero)*interval,amount));}return result;}
    public GArray humanize(GArray notes,double timing,double velocity,long seed){var result=notes.Duplicate(true);using var rng=new RandomNumberGenerator{Seed=unchecked((ulong)seed)};foreach(var raw in result){var note=raw.AsGodotDictionary();note["start"]=Math.Max(0,note["start"].AsDouble()+rng.RandfRange(-(float)Math.Abs(timing),(float)Math.Abs(timing)));note["velocity"]=Math.Clamp(Get(note,"velocity",.8).AsDouble()+rng.RandfRange(-(float)Math.Abs(velocity),(float)Math.Abs(velocity)),0,1);}return result;}
    public Godot.Collections.Array<Settings> arpeggiate(GArray pitches,double start,double duration,double step,string direction)
    {
        var result=new Godot.Collections.Array<Settings>();if(pitches.Count==0)return result;var ordered=new System.Collections.Generic.List<int>();foreach(var pitch in pitches)ordered.Add(pitch.AsInt32());ordered.Sort();if(direction=="down")ordered.Reverse();if(direction=="up_down"&&ordered.Count>2){var back=ordered.GetRange(1,ordered.Count-2);back.Reverse();ordered.AddRange(back);}double spacing=Math.Max(.03125,step);int count=(int)Math.Min(8192,Math.Ceiling(duration/spacing));for(int i=0;i<count;++i)result.Add(new_note(ordered[i%ordered.Count],start+i*spacing,Math.Min(spacing*.8,duration-i*spacing),i%ordered.Count==0?.8:.65,0));return result;
    }
    public GArray harmonize(GArray notes,Variant key,string scale,int interval){var result=notes.Duplicate(true);int root=key_pitch(key);var values=Scale(scale);foreach(var raw in result){var note=raw.AsGodotDictionary();int pitch=quantize_pitch(note["pitch"].AsInt32(),root,scale),degree=Array.IndexOf(values,Mod(pitch-root,12)),octave=(int)Math.Floor((pitch-root)/12.0);note["pitch"]=Math.Clamp(scale_pitch(degree+interval,root+octave*12,scale),0,127);note["id"]=Id();}return result;}
}
